const catalogue=PRODUCTS;
const leagues=['Premier League','La Liga','Serie A','Bundesliga','Ligue 1'];
const categories=['All','Football kits','Football boots','Footballs','Socks','Training wear','Bags','Accessories'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let currency='USD',cart=[],favourites=[],toastTimer;
try{currency=localStorage.getItem('valeria-currency')==='CNY'?'CNY':'USD';const saved=JSON.parse(localStorage.getItem('pitchside-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>catalogue.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20&&typeof x.size==='string').map(x=>({id:x.id,size:x.size.slice(0,50),qty:x.qty}));const fav=JSON.parse(localStorage.getItem('valeria-favourites')||'[]');if(Array.isArray(fav))favourites=fav.filter(id=>catalogue.some(p=>p.id===id));}catch{}
const state={category:'All',league:'',club:'',season:'',variant:'',brand:'',era:'',family:'',search:'',sort:'featured',page:1,favourites:false};
const pageSize=24;
const amount=n=>currency==='CNY'?Math.round(n*6.674*100)/100:n;
const format=n=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(n);
const money=n=>Number.isFinite(n)?format(amount(n)):'Price on enquiry';
const productById=id=>catalogue.find(p=>p.id===id);
const hasPrice=p=>Number.isFinite(p.price);
const priceLabel=p=>!hasPrice(p)?'Quote required':/estimate/i.test(p.pricing?.kind||'')?'Estimated retail':/Resale/.test(p.pricing?.kind||'')?'Resale asking price':/Launch/.test(p.pricing?.kind||'')?'Launch retail':/Archived/.test(p.pricing?.kind||'')?'Archived retail':'Retail reference';
const displayPrice=p=>(/estimate/i.test(p.pricing?.kind||'')?'≈ ':'')+money(p.price);
function pricingInfo(p){const q=p.pricing||{};return `<div class="pricing-info"><b>${esc(q.kind||'Price reference')}</b><p>${esc(q.note||'')}</p>${q.originalAmount?`<span>Source amount: ${esc(q.originalCurrency)} ${Number(q.originalAmount).toFixed(2)} · Reviewed ${esc(q.checked)}</span>`:`<span>Reviewed ${esc(q.checked||'2026-11-05')}</span>`}${q.source?`<a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">View price source ↗</a>`:''}${currency==='CNY'?'<small>Yuan amounts are approximate USD conversions at 1 USD = 6.674 CNY (4 Nov 2026), not local Chinese retail quotations.</small>':''}</div>`}

function persist(){try{localStorage.setItem('pitchside-cart-v1',JSON.stringify(cart));localStorage.setItem('valeria-favourites',JSON.stringify(favourites));localStorage.setItem('valeria-currency',currency)}catch{}updateCounts()}
function updateCounts(){document.querySelector('#bag-count').textContent=cart.reduce((s,x)=>s+x.qty,0);document.querySelector('#favourite-count').textContent=favourites.length;document.querySelector('#show-favourites').setAttribute('aria-pressed',String(state.favourites));}
function toast(text){const e=document.querySelector('#toast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2800)}
function imageMarkup(p){if(p.image)return `<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" decoding="async">`;return `<div class="photo-pending"><span>V.</span><b>Product photo pending</b><small>${esc(p.club||p.brand||'Valeria Sports Wears')}</small></div>`;}
function card(p){const saved=favourites.includes(p.id);const descriptor=p.category==='Football kits'?`${p.season} · ${p.variant}`:p.brand?`${p.brand} · ${p.category==='Football boots'?(p.era||'Football'):p.category}`:p.category;return `<article class="product-card"><div class="product-image"><button class="image-link" data-product="${p.id}" aria-label="View ${esc(p.name)}">${imageMarkup(p)}</button><span class="tag">${esc(p.tag||p.variant||p.era||p.category)}</span><button class="favourite ${saved?'saved':''}" data-favourite="${p.id}" aria-pressed="${saved}" aria-label="${saved?'Remove':'Save'} ${esc(p.name)} ${saved?'from':'to'} favourites">${saved?'♥':'♡'}</button></div><div class="product-info"><span class="category">${esc(descriptor)}</span><h3><button data-product="${p.id}">${esc(p.category==='Football kits'?p.club+' '+p.variant+' Shirt':p.name)}</button></h3><span class="price ${hasPrice(p)?'':'enquire-price'}">${displayPrice(p)}</span><span class="price-kind">${priceLabel(p)}</span><small>${esc(p.league||p.brand||'Match-day essentials')}</small><button class="quick-add" data-product="${p.id}" aria-label="View details for ${esc(p.name)}">↗</button></div></article>`}
function filterItems(){let rows=catalogue.filter(p=>(state.category==='All'||p.category===state.category)&&(!state.league||p.league===state.league)&&(!state.club||p.club===state.club)&&(!state.season||p.season===state.season)&&(!state.variant||p.variant===state.variant)&&(!state.brand||p.brand===state.brand)&&(!state.era||p.era===state.era)&&(!state.family||p.family===state.family)&&(!state.favourites||favourites.includes(p.id))&&normalize([p.name,p.club,p.brand,p.league,p.season,p.variant,p.era,p.player,p.family,p.signature,p.edition].join(' ')).includes(normalize(state.search)));
if(state.sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));if(state.sort==='latest')rows.sort((a,b)=>(b.season||'').localeCompare(a.season||''));if(state.sort==='low')rows.sort((a,b)=>(hasPrice(a)?a.price:Infinity)-(hasPrice(b)?b.price:Infinity));if(state.sort==='high')rows.sort((a,b)=>(hasPrice(b)?b.price:-Infinity)-(hasPrice(a)?a.price:-Infinity));return rows;}
function setOptions(id,options,placeholder,value){const el=document.querySelector('#'+id);el.innerHTML=`<option value="">${placeholder}</option>`+options.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');el.value=value;}
function refreshFilterOptions(){setOptions('filter-league',leagues,'All five leagues',state.league);setOptions('filter-season',['2026/27','2025/26'],'Both seasons',state.season);const clubs=[...new Set(catalogue.filter(p=>(!state.league||p.league===state.league)&&(!state.season||p.season===state.season)).map(p=>p.club).filter(Boolean))].sort((a,b)=>a.localeCompare(b));if(state.club&&!clubs.includes(state.club))state.club='';setOptions('filter-club',clubs,'All clubs',state.club);setOptions('filter-variant',['Home','Away'],'Home & away',state.variant);setOptions('filter-brand',[...new Set(catalogue.map(p=>p.brand).filter(Boolean))].sort(),'All brands',state.brand);setOptions('filter-era',['Modern','Classic'],'New & classic',state.era);setOptions('filter-family',[...new Set(catalogue.filter(p=>p.category==='Football boots').map(p=>p.family).filter(Boolean))].sort(),'All boot families',state.family);}
function render(){refreshFilterOptions();document.querySelector('.filters').innerHTML=categories.map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}" aria-pressed="${state.category===c}">${c}</button>`).join('');let rows=filterItems(),pages=Math.max(1,Math.ceil(rows.length/pageSize));state.page=Math.min(state.page,pages);const start=(state.page-1)*pageSize,visible=rows.slice(start,start+pageSize);document.querySelector('#products').innerHTML=visible.map(card).join('');document.querySelector('#result-count').textContent=rows.length?`${start+1}–${Math.min(start+pageSize,rows.length)} of ${rows.length} products`:'0 products';document.querySelector('#catalogue-label').textContent=state.favourites?'Your saved favourites':'The complete line-up';document.querySelector('#empty-search').hidden=rows.length>0;document.querySelector('#pagination').innerHTML=rows.length>pageSize?`<button id="previous-page" ${state.page===1?'disabled':''}>← Previous</button><span>Page ${state.page} of ${pages}</span><button id="next-page" ${state.page===pages?'disabled':''}>Next →</button>`:'';document.querySelector('#active-filters').innerHTML=Object.entries(state).filter(([k,v])=>['league','club','season','variant','brand','era','family'].includes(k)&&v).map(([k,v])=>`<button data-clear="${k}" aria-label="Remove ${esc(v)} filter">${esc(v)} ×</button>`).join('')+(state.favourites?'<button data-clear="favourites">Favourites ×</button>':'');document.querySelector('#search').value=state.search;document.querySelector('#sort').value=state.sort;document.querySelector('#filter-count').textContent=Object.entries(state).filter(([k,v])=>['league','club','season','variant','brand','era','family'].includes(k)&&v).length;bindGrid();updateCounts();}
function bindGrid(){document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.product));document.querySelectorAll('[data-favourite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favourite;if(favourites.includes(id))favourites=favourites.filter(x=>x!==id);else favourites.push(id);persist();render()});document.querySelectorAll('.filters [data-category]').forEach(b=>b.onclick=()=>chooseCategory(b.dataset.category));document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{state[b.dataset.clear]=b.dataset.clear==='favourites'?false:'';state.page=1;render()});const prev=document.querySelector('#previous-page'),next=document.querySelector('#next-page');if(prev)prev.onclick=()=>changePage(-1);if(next)next.onclick=()=>changePage(1);}
function changePage(delta){state.page+=delta;render();document.querySelector('#shop').scrollIntoView({behavior:'smooth'})}
function chooseCategory(category){Object.assign(state,{category,league:'',club:'',season:'',variant:'',brand:'',era:'',family:'',search:'',page:1,favourites:false});render();}
function clearFilters(){Object.assign(state,{category:'All',league:'',club:'',season:'',variant:'',brand:'',era:'',family:'',search:'',page:1,favourites:false});render()}
function bindClose(d){d.querySelector('.close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}}
function openProduct(id){const p=productById(id);if(!p)return;const sizes=p.sizes?.length?p.sizes:p.category==='Football boots'?['UK 6','UK 7','UK 8','UK 9','UK 10','UK 11']:['S','M','L','XL','XXL'];let size=sizes[0];const d=document.querySelector('#product-modal');d.innerHTML=`<div class="dialog-head"><span class="eyebrow">VALERIA SPORTS WEARS / ${esc(p.category)}</span><button class="close" aria-label="Close product details">×</button></div><div class="product-detail"><div class="detail-art">${imageMarkup(p)}${p.gallery?.length>1?`<div class="photo-thumbs">${p.gallery.map((src,i)=>`<button data-photo="${esc(src)}" aria-label="View product photo ${i+1}"><img src="${esc(src)}" alt="Product photo ${i+1}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="eyebrow">${esc(p.league||p.brand||p.category)}</span><h2 id="product-title">${esc(p.name)}</h2><div class="price">${displayPrice(p)}</div>${pricingInfo(p)}<div class="product-facts">${[p.season,p.variant,p.era,p.edition,p.signature].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div><p>${esc(p.detail)}</p>${p.referenceStatus==='Source marked as leak'?'<p class="reference-note">Design reference: the source gallery marks this image as a leak. Final release details need confirmation.</p>':''}<div class="size-label">REQUESTED SIZE <span>Availability to be confirmed</span></div><div class="sizes" role="group" aria-label="Requested size">${sizes.map((s,i)=>`<button class="${i===0?'selected':''}" aria-pressed="${i===0}" data-size="${esc(s)}">${esc(s)}</button>`).join('')}</div><button class="btn dark" id="add-to-bag">Add to ${hasPrice(p)?'bag':'enquiry'} <span>+</span></button><p class="sample-note">Catalogue preview. No order or payment is submitted. ${hasPrice(p)?'Market references and estimates are not confirmed seller offers; taxes and delivery are excluded.':'Ask for price, stock and condition before purchase.'}</p>${p.source?`<a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Product & photo reference ↗</a>`:''}</div></div>`;bindClose(d);d.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{d.querySelector('.detail-art>img').src=b.dataset.photo});d.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{size=b.dataset.size;d.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});d.querySelector('#add-to-bag').onclick=()=>{const existing=cart.find(x=>x.id===id&&x.size===size);if(existing?.qty>=20){toast('Maximum 20 of each item.');return}if(existing)existing.qty++;else cart.push({id,size,qty:1});persist();d.close();toast('Added to your selection')};d.showModal()}
function total(){return cart.reduce((sum,x)=>{const p=productById(x.id);return sum+(hasPrice(p)?amount(p.price)*x.qty:0)},0)}
function enquiryText(){return 'VALERIA SPORTS WEARS — PRODUCT ENQUIRY\n\n'+cart.map(x=>{const p=productById(x.id);return `${p.name}\nRequested size: ${x.size} | Quantity: ${x.qty}\n${hasPrice(p)?'Reference / estimated amount: '+format(amount(p.price)*x.qty):'Price and stock: please confirm'}\nReference: ${p.source||'Store catalogue'}`}).join('\n\n')+'\n\nReference subtotal: '+format(total())+'\nCurrency: '+currency+'\nEstimates are included; quote-only items are excluded. This is not a payable total.\nThis document is a saved enquiry, not an order. It has not been sent to the seller. No payment has been taken. Shipping and taxes are not calculated.'}
function downloadEnquiry(){const blob=new Blob([enquiryText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='valeria-sports-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderCart(){const d=document.querySelector('#cart-modal'),unpriced=cart.filter(x=>!hasPrice(productById(x.id))).reduce((s,x)=>s+x.qty,0);d.innerHTML=`<div class="dialog-head"><h2 id="cart-title">Your selection <span>(${cart.reduce((s,x)=>s+x.qty,0)})</span></h2><button class="close" aria-label="Close shopping bag">×</button></div><div class="cart-content">${cart.length?cart.map((x,i)=>{const p=productById(x.id);return `<div class="cart-row"><div class="cart-art">${imageMarkup(p)}</div><div><h3>${esc(p.name)}</h3><p>Requested size: ${esc(x.size)}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Decrease quantity of ${esc(p.name)}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Increase quantity of ${esc(p.name)}">+</button></div></div><div><span class="price">${hasPrice(p)?format(amount(p.price)*x.qty):'Price on enquiry'}</span><button class="remove" data-remove="${i}" aria-label="Remove ${esc(p.name)}">Remove</button></div></div>`}).join('')+`<div class="cart-total"><span>Reference subtotal</span><span>${cart.some(x=>hasPrice(productById(x.id)))?format(total()):'Quote required'}</span></div>${unpriced?`<p class="enquiry-count">${unpriced} ${unpriced===1?'item requires':'items require'} a price quote. These items are excluded from the subtotal.</p>`:''}<p class="cart-note">Reference subtotal includes retail benchmarks and estimates. Taxes and delivery are excluded. Save your selection as an enquiry; seller prices and stock require confirmation. No order will be placed or message sent.</p><div class="cart-actions"><button class="btn dark" id="download-order">Download enquiry <span>↓</span></button><button class="btn light" id="keep-shopping">Keep browsing</button></div>`:`<div class="cart-empty"><h3>Your next match starts here.</h3><p>Add kits or boots to build your selection.</p><button class="btn dark" id="keep-shopping">Explore the catalogue ↗</button></div>`}</div>`;bindClose(d);d.querySelector('#keep-shopping').onclick=()=>d.close();d.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const row=cart[Number(b.dataset.qty)],next=row.qty+Number(b.dataset.delta);if(next>20){toast('Maximum 20 of each item.');return}if(next===0)cart.splice(Number(b.dataset.qty),1);else row.qty=next;persist();renderCart()});d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);persist();renderCart()});const download=d.querySelector('#download-order');if(download)download.onclick=downloadEnquiry;}
document.querySelector('#open-cart').onclick=()=>{renderCart();document.querySelector('#cart-modal').showModal()};document.querySelector('#currency').value=currency;document.querySelector('#currency').onchange=e=>{currency=e.target.value;persist();render()};document.querySelector('#show-favourites').onclick=()=>{const show=!state.favourites;clearFilters();state.favourites=show;state.page=1;render();document.querySelector('#shop').scrollIntoView({behavior:'smooth'})};document.querySelector('#search').oninput=e=>{state.search=e.target.value;state.page=1;render()};document.querySelector('#sort').onchange=e=>{state.sort=e.target.value;state.page=1;render()};document.querySelector('#clear-filters').onclick=clearFilters;document.querySelector('#empty-reset').onclick=clearFilters;for(const key of ['league','club','season','variant','brand','era','family'])document.querySelector('#filter-'+key).onchange=e=>{state[key]=e.target.value;if(['league','club','season','variant'].includes(key)&&e.target.value){if(key==='variant'||!['Training wear','Socks'].includes(state.category))state.category='Football kits';state.brand='';state.era='';state.family='';}if(['era','family'].includes(key)&&e.target.value){state.category='Football boots';state.league='';state.club='';state.season='';state.variant='';}state.page=1;render()};document.querySelector('#toggle-filters').onclick=()=>{const panel=document.querySelector('.catalogue-sidebar');const opened=panel.classList.toggle('opened');document.querySelector('#toggle-filters').setAttribute('aria-expanded',String(opened));if(opened)panel.scrollIntoView({behavior:'smooth',block:'nearest'})};document.querySelectorAll('a[data-category]').forEach(a=>a.onclick=()=>chooseCategory(a.dataset.category));document.querySelectorAll('[data-league]').forEach(a=>a.onclick=()=>{clearFilters();state.category='Football kits';state.league=a.dataset.league;render()});document.querySelectorAll('[data-collection]').forEach(a=>a.onclick=()=>{clearFilters();state.category='Football boots';state.era=a.dataset.collection;render()});
document.querySelector('#catalogue-total').textContent=catalogue.filter(p=>p.category==='Football kits').length;document.querySelector('#boot-total').textContent=catalogue.filter(p=>p.category==='Football boots').length;document.querySelectorAll('[data-league-count]').forEach(e=>e.textContent=catalogue.filter(p=>p.category==='Football kits'&&p.league===e.dataset.leagueCount).length+' shirts');document.querySelector('#hero-shirt').innerHTML=imageMarkup(productById('f50-yamal-heartbreaker')).replace('loading="lazy"','loading="eager" fetchpriority="high"');document.querySelector('#collection-art').innerHTML=imageMarkup(productById('f50-yamal-purple'));document.querySelectorAll('[data-player]').forEach(a=>a.onclick=()=>{clearFilters();state.category='Football boots';state.search=a.dataset.player;render()});document.querySelectorAll('[data-family]').forEach(a=>a.onclick=()=>{clearFilters();state.category='Football boots';state.family=a.dataset.family;render()});render();
